  /**
   * @method
   * @name aster#fetchOrders
   * @description fetches information on multiple orders made by the user
   * @see
   * https://asterdex.github.io/aster-api-website/spot-v3/account%26trades/#query-all-orders-user_data
   * @see
   * https://asterdex.github.io/aster-api-website/futures-v3/account%26trades/#all-orders-user_data
   * @param {string} symbol unified market symbol of the market orders were made
   * in
   * @param {int} [since] the earliest time in ms to fetch orders for
   * @param {int} [limit] the maximum number of order structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] the latest time in ms to fetch orders for
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  fetchOrders(std::any symbol = std::any{}, std::any since = std::any{},
              std::any limit = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(symbol, std::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(
                               " fetchOrders() requires a symbol argument"))));
                 }
                 awaitValue(this->loadMarketsAndSignIn());
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("limit"),
                              mathMin(limit, 1000));
                 }
                 if (isTrue(!isEqual(since, std::any{}))) {
                   ::setValue(request, std::string("startTime"), since);
                 }
                 std::any requestparamsVariable = this->handleUntilOption(
                     std::string("endTime"), request, params);
                 request = ::getValue(requestparamsVariable, 0);
                 params = ::getValue(requestparamsVariable, 1);
                 std::any response = std::any{};
                 if (isTrue(isEqual(::getValue(market, std::string("swap")),
                                    true))) {
                   response = awaitValue(this->fapiPrivateGetV3AllOrders(
                       this->extend(request, params)));
                 } else {
                   response = awaitValue(this->sapiPrivateGetV3AllOrders(
                       this->extend(request, params)));
                 }
                 //
                 // SPOT & SWAP has similar responses
                 //
                 //    [
                 //        {
                 //            "orderId": "417594542",
                 //            "symbol": "ETHUSDT",
                 //            "status": "FILLED",
                 //            "clientOrderId": "web_qnvMAhOJsiVbSyu0BdKG",
                 //            "price": "0",                     // value set
                 //            for unfilled "avgPrice": "2351.580000",        //
                 //            value zero for unfilled "origQty": "0.0054",
                 //            "executedQty": "0.0054",          // value zero
                 //            for unfilled "cumQuote": "12.69853200",        //
                 //            value zero for unfilled "timeInForce": "GTC",
                 //            "type": "MARKET",
                 //            "side": "SELL",
                 //            "stopPrice": "0",
                 //            "origType": "MARKET",
                 //            "time": "1776274219582",
                 //            "updateTime": "1776274219609",
                 //            "orderListId": "-1", // only in SPOT
                 //            "reduceOnly": false, // only in PERP
                 //            "closePosition": false, // only in PERP
                 //            "positionSide": "BOTH", // only in PERP
                 //            "workingType": "CONTRACT_PRICE", // only in PERP
                 //            "priceProtect": false, // only in PERP
                 //            "newChainData": { "hash": "0xe17d3d5b...dbca8b01"
                 //            }      // only in PERP
                 //        }, ...
                 //
                 return this->parseOrders(response, market, since, limit);
               })
        .share();
  }

  /**
   * @method
   * @name aster#fetchOpenOrders
   * @description fetch all unfilled currently open orders
   * @see
   * https://asterdex.github.io/aster-api-website/spot-v3/account%26trades/#current-open-orders-user_data
   * @see
   * https://asterdex.github.io/aster-api-website/futures-v3/account%26trades/#current-all-open-orders-user_data
   * @param {string} symbol unified market symbol
   * @param {int} [since] the earliest time in ms to fetch open orders for
   * @param {int} [limit] the maximum number of  open orders structures to
   * retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.subType] "linear" or "inverse"
   * @param {string} [params.type] 'spot', 'option', use params["subType"] for
   * swap and future markets
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  fetchOpenOrders(std::any symbol = std::any{}, std::any since = std::any{},
                  std::any limit = std::any{},
                  std::any params = ccxt::dict{}) override {
    return std::
        async(std::launch::deferred,
              [=]() mutable -> std::any {
                awaitValue(this->loadMarketsAndSignIn());
                std::any request = ccxt::dict{};
                std::any market = std::any{};
                std::any marketType = std::any{};
                if (isTrue(!isEqual(symbol, std::any{}))) {
                  market = this->market(symbol);
                  ::setValue(request, std::string("symbol"),
                             ::getValue(market, std::string("id")));
                }
                if (isTrue(isEqual(symbol, std::any{}))) {
                  if (isTrue(isEqual(
                          ::getValue(::getValue(this->options,
                                                std::string("fetchOpenOrders")),
                                     std::string("warnIfNoSymbol")),
                          true))) {
                    throw ExchangeError(toString(add(
                        add(add(this->id,
                                std::string(
                                    " fetchOpenOrders(): WARNING - this method "
                                    "without providing \"symbol\" argument "
                                    "uses 40 times more rate-limit quota. If "
                                    "you acknowledge this warning, set ")),
                            this->id),
                        std::string(
                            ".options[\"fetchOpenOrders\"][\"warnIfNoSymbol\"] "
                            "= false to suppress this warning message."))));
                  }
                } else {
                  market = this->market(symbol);
                  ::setValue(request, std::string("symbol"),
                             ::getValue(market, std::string("id")));
                }
                std::any marketTypeparamsVariable =
                    this->handleMarketTypeAndParams(
                        std::string("fetchOpenOrders"), market, params);
                marketType = ::getValue(marketTypeparamsVariable, 0);
                params = ::getValue(marketTypeparamsVariable, 1);
                std::any subType = std::any{};
                std::any subTypeparamsVariable = this->handleSubTypeAndParams(
                    std::string("fetchOpenOrders"), market, params);
                subType = ::getValue(subTypeparamsVariable, 0);
                params = ::getValue(subTypeparamsVariable, 1);
                std::any response = std::any{};
                if (isTrue(this->isLinear(marketType, subType))) {
                  response = awaitValue(this->fapiPrivateGetV3OpenOrders(
                      this->extend(request, params)));
                } else if (isTrue(isEqual(marketType, std::string("spot")))) {
                  response = awaitValue(this->sapiPrivateGetV3OpenOrders(
                      this->extend(request, params)));
                }
                //
                // SPOT & SWAP has similar responses
                //
                //    [
                //        {
                //            "orderId": "17338239315",
                //            "symbol": "ETHUSDT",
                //            "status": "NEW",
                //            "clientOrderId": "web_AD_mbhgla7k15gptmwyr_x",
                //            "price": "2216.62",
                //            "avgPrice": "0",
                //            "origQty": "0.012",
                //            "executedQty": "0",
                //            "cumQuote": "0",
                //            "timeInForce": "GTC",
                //            "type": "LIMIT",
                //            "side": "BUY",
                //            "stopPrice": "0",
                //            "origType": "LIMIT",
                //            "time": "1776798208476",
                //            "updateTime": "1776798208450",
                //            "orderListId": "-1" // only in SPOT "reduceOnly":
                //            false,                                  // only in
                //            PERP "closePosition": false, // only in PERP
                //            "positionSide": "BOTH", // only in PERP
                //            "workingType": "CONTRACT_PRICE", // only in PERP
                //            "priceProtect": false, // only in PERP
                //            "newChainData": { "hash": "0xf8a496....a7fd5" } //
                //            only in PERP
                //        }
                //    ]
                //
                return this->parseOrders(response, market, since, limit);
              })
            .share();
  }

  /**
   * @method
   * @name aster#createOrder
   * @description create a trade order
   * @see
   * https://asterdex.github.io/aster-api-website/spot-v3/account%26trades/#place-order-trade
   * @see
   * https://asterdex.github.io/aster-api-website/futures-v3/account%26trades/#new-order-trade
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} type 'market' or 'limit' or 'STOP' or 'STOP_MARKET' or
   * 'TAKE_PROFIT' or 'TAKE_PROFIT_MARKET' or 'TRAILING_STOP_MARKET'
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount how much of you want to trade in units of the base
   * currency
   * @param {float} [price] the price that the order is to be fulfilled, in
   * units of the quote currency, ignored in market orders
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.reduceOnly] for swap and future reduceOnly is a
   * string 'true' or 'false' that cant be sent with close position set to true
   * or in hedge mode. For spot margin and option reduceOnly is a boolean.
   * @param {boolean} [params.test] whether to use the test endpoint or not,
   * default is false
   * @param {float} [params.trailingPercent] the percent to trail away from the
   * current market price
   * @param {float} [params.trailingTriggerPrice] the price to trigger a
   * trailing order, default uses the price argument
   * @param {string} [params.positionSide] "BOTH" for one-way mode, "LONG" for
   * buy side of hedged mode, "SHORT" for sell side of hedged mode
   * @param {float} [params.triggerPrice] the price that a trigger order is
   * triggered at
   * @param {float} [params.stopLossPrice] the price that a stop loss order is
   * triggered at
   * @param {float} [params.takeProfitPrice] the price that a take profit order
   * is triggered at
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  createOrder(std::any symbol, std::any type, std::any side, std::any amount,
              std::any price = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 awaitValue(this->loadMarketsAndSignIn());
                 std::any market = this->market(symbol);
                 std::any request = this->createOrderRequest(
                     symbol, type, side, amount, price, params);
                 std::any response = std::any{};
                 if (isTrue(isEqual(::getValue(market, std::string("swap")),
                                    true))) {
                   response = awaitValue(this->fapiPrivatePostV3Order(request));
                 } else {
                   response = awaitValue(this->sapiPrivatePostV3Order(request));
                 }
                 //
                 // SPOT & SWAP has similar responses
                 //
                 //    {
                 //        "orderId": "17338441758",
                 //        "symbol": "ETHUSDT",
                 //        "status": "NEW",
                 //        "clientOrderId": "727Wt3TIUgkUCxXp20E543",
                 //        "price": "0",
                 //        "avgPrice": "0.00000",
                 //        "origQty": "0.010",
                 //        "executedQty": "0",
                 //        "cumQty": "0",
                 //        "cumQuote": "0",
                 //        "timeInForce": "GTC",
                 //        "type": "MARKET",
                 //        "side": "BUY",
                 //        "stopPrice": "0",
                 //        "origType": "MARKET",
                 //        "time": "1776800300700",
                 //        "updateTime": "1776800300700",
                 //        "orderListId": "-1",                              //
                 //        only in SPOT "workingType": "CONTRACT_PRICE", // only
                 //        in PERP "positionSide": "BOTH", // only in PERP
                 //        "reduceOnly": false,                              //
                 //        only in PERP "closePosition": false, // only in PERP
                 //        "priceProtect": false,                            //
                 //        only in PERP "newChainData": { "hash":
                 //        "0x46ae....c8ba" }      // only in PERP
                 //    }
                 //
                 return this->parseOrder(response, market);
               })
        .share();
  }

  /**
   * @method
   * @name aster#createOrders
   * @description create a list of trade orders
   * @see
   * https://asterdex.github.io/aster-api-website/futures-v3/account%26trades/#new-order-trade
   * @param {Array} orders list of orders to create, each object should contain
   * the parameters required by createOrder, namely symbol, type, side, amount,
   * price and params
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  createOrders(std::any orders, std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 awaitValue(this->loadMarketsAndSignIn());
                 std::any ordersRequests = ccxt::list{};
                 std::any orderSymbols = ccxt::list{};
                 if (isTrue(isGreaterThan(getArrayLength(orders), 5))) {
                   throw InvalidOrder(toString(
                       add(this->id,
                           std::string(
                               " createOrders() order list max 5 orders"))));
                 }
                 for (std::any i = 0; isLessThan(i, getArrayLength(orders));
                      postFixIncrement(i)) {
                   std::any rawOrder = ::getValue(orders, i);
                   std::any marketId =
                       this->safeString(rawOrder, std::string("symbol"));
                   std::any currentMarket = this->market(marketId);
                   arrayPush(orderSymbols,
                             ::getValue(currentMarket, std::string("symbol")));
                   std::any type =
                       this->safeString(rawOrder, std::string("type"));
                   std::any side =
                       this->safeString(rawOrder, std::string("side"));
                   std::any amount =
                       this->safeValue(rawOrder, std::string("amount"));
                   std::any price =
                       this->safeValue(rawOrder, std::string("price"));
                   std::any orderParams = this->safeDict(
                       rawOrder, std::string("params"), ccxt::dict{});
                   std::any orderRequest = this->createOrderRequest(
                       marketId, type, side, amount, price, orderParams);
                   arrayPush(ordersRequests, orderRequest);
                 }
                 orderSymbols = this->marketSymbols(orderSymbols, std::any{},
                                                    false, true, true);
                 std::any market = this->market(::getValue(orderSymbols, 0));
                 if (isTrue(isEqual(::getValue(market, std::string("spot")),
                                    true))) {
                   throw NotSupported(toString(
                       add(add(add(this->id,
                                   std::string(
                                       " createOrders() does not support ")),
                               ::getValue(market, std::string("type"))),
                           std::string(" orders"))));
                 }
                 std::any request = ccxt::dict{
                     {std::string("batchOrders"), ordersRequests},
                 };
                 std::any response =
                     awaitValue(this->fapiPrivatePostV3BatchOrders(
                         this->extend(request, params)));
                 //
                 //    [
                 //        {
                 //            "orderId": 17338699853,
                 //            "symbol": "ETHUSDT",
                 //            "status": "NEW",
                 //            "clientOrderId": "NxMWPvOEyiF6TWh5UB8BQf0",
                 //            "price": "0",
                 //            "avgPrice": "0.00000",
                 //            "origQty": "0.010",
                 //            "executedQty": "0",
                 //            "cumQty": "0",
                 //            "cumQuote": "0",
                 //            "timeInForce": "GTC",
                 //            "type": "MARKET",
                 //            "reduceOnly": false,
                 //            "closePosition": false,
                 //            "side": "BUY",
                 //            "positionSide": "BOTH",
                 //            "stopPrice": "0",
                 //            "workingType": "CONTRACT_PRICE",
                 //            "priceProtect": false,
                 //            "origType": "MARKET",
                 //            "updateTime": 1776802276050,
                 //            "newChainData": {
                 //                "hash":
                 //                "0x5e569d9794cf726f72c2d000d401d20315e78e4df7b58023a489864624527dfe"
                 //            }
                 //        }
                 //    ]
                 //
                 return this->parseOrders(response);
               })
        .share();
  }

  virtual std::any createOrderRequest(std::any symbol, std::any type,
                                      std::any side, std::any amount,
                                      std::any price = std::any{},
                                      std::any params = ccxt::dict{}) {
    if (isTrue(isEqual(type, std::any{}))) {
      throw ArgumentsRequired(
          toString(add(this->id, std::string(" requires a type argument"))));
    }
    if (isTrue(isEqual(side, std::any{}))) {
      throw ArgumentsRequired(
          toString(add(this->id, std::string(" requires a side argument"))));
    }
    /**
     * @method
     * @ignore
     * @name aster#createOrderRequest
     * @description helper function to build the request
     * @param {string} symbol unified symbol of the market to create an order in
     * @param {string} type 'market' or 'limit'
     * @param {string} side 'buy' or 'sell'
     * @param {float} amount how much you want to trade in units of the base
     * currency
     * @param {float} [price] the price that the order is to be fulfilled, in
     * units of the quote currency, ignored in market orders
     * @param {object} [params] extra parameters specific to the exchange API
     * endpoint
     * @returns {object} request to be sent to the exchange
     */
    std::any market = this->market(symbol);
    std::any initialUppercaseType = toUpperCase(type);
    std::any isMarketOrder =
        isEqual(initialUppercaseType, std::string("MARKET"));
    std::any isLimitOrder = isEqual(initialUppercaseType, std::string("LIMIT"));
    std::any request = ccxt::dict{
        {std::string("symbol"), ::getValue(market, std::string("id"))},
        {std::string("side"), toUpperCase(side)},
    };
    std::any clientOrderId = this->safeString2(
        params, std::string("newClientOrderId"), std::string("clientOrderId"));
    if (isTrue(!isEqual(clientOrderId, std::any{}))) {
      ::setValue(request, std::string("newClientOrderId"), clientOrderId);
    }
    std::any triggerPrice = this->safeString2(
        params, std::string("triggerPrice"), std::string("stopPrice"));
    std::any stopLossPrice =
        this->safeString(params, std::string("stopLossPrice"), triggerPrice);
    std::any takeProfitPrice =
        this->safeString(params, std::string("takeProfitPrice"));
    std::any trailingDelta =
        this->safeString(params, std::string("trailingDelta"));
    std::any trailingTriggerPrice =
        this->safeString2(params, std::string("trailingTriggerPrice"),
                          std::string("activationPrice"));
    std::any trailingPercent =
        this->safeStringN(params, ccxt::list{std::string("trailingPercent"),
                                             std::string("callbackRate"),
                                             std::string("trailingDelta")});
    std::any isTrailingPercentOrder = !isEqual(trailingPercent, std::any{});
    std::any isStopLoss = isTrue(!isEqual(stopLossPrice, std::any{})) ||
                          isTrue(!isEqual(trailingDelta, std::any{}));
    std::any isTakeProfit = !isEqual(takeProfitPrice, std::any{});
    std::any uppercaseType = initialUppercaseType;
    std::any stopPrice = std::any{};
    if (isTrue(isTrailingPercentOrder)) {
      if (isTrue(isEqual(::getValue(market, std::string("swap")), true))) {
        uppercaseType = std::string("TRAILING_STOP_MARKET");
        ::setValue(request, std::string("callbackRate"), trailingPercent);
        if (isTrue(!isEqual(trailingTriggerPrice, std::any{}))) {
          ::setValue(request, std::string("activationPrice"),
                     this->priceToPrecision(symbol, trailingTriggerPrice));
        }
      }
    } else if (isTrue(isStopLoss)) {
      stopPrice = stopLossPrice;
      if (isTrue(isMarketOrder)) {
        uppercaseType = std::string("STOP_MARKET");
      } else if (isTrue(isLimitOrder)) {
        uppercaseType = std::string("STOP");
      }
    } else if (isTrue(isTakeProfit)) {
      stopPrice = takeProfitPrice;
      if (isTrue(isMarketOrder)) {
        uppercaseType = std::string("TAKE_PROFIT_MARKET");
      } else if (isTrue(isLimitOrder)) {
        uppercaseType = std::string("TAKE_PROFIT");
      }
    }
    std::any postOnly = this->isPostOnly(isMarketOrder, std::any{}, params);
    if (isTrue(postOnly)) {
      ::setValue(request, std::string("timeInForce"), std::string("GTX"));
    }
    //
    // spot
    // LIMIT timeInForce, quantity, price
    // MARKET quantity or quoteOrderQty
    // STOP and TAKE_PROFIT quantity, price, stopPrice
    // STOP_MARKET and TAKE_PROFIT_MARKET quantity, stopPrice
    // future
    // LIMIT timeInForce, quantity, price
    // MARKET quantity
    // STOP/TAKE_PROFIT quantity, price, stopPrice
    // STOP_MARKET/TAKE_PROFIT_MARKET stopPrice
    // TRAILING_STOP_MARKET callbackRate
    //
    // additional required fields depending on the order type
    std::any closePosition =
        this->safeBool(params, std::string("closePosition"), false);
    std::any timeInForceIsRequired = false;
    std::any priceIsRequired = false;
    std::any triggerPriceIsRequired = false;
    std::any quantityIsRequired = false;
    ::setValue(request, std::string("type"), uppercaseType);
    if (isTrue(isEqual(uppercaseType, std::string("MARKET")))) {
      if (isTrue(isEqual(::getValue(market, std::string("spot")), true))) {
        std::any quoteOrderQty = this->handleOption(
            std::string("createOrder"), std::string("quoteOrderQty"), true);
        if (isTrue(isEqual(quoteOrderQty, true))) {
          std::any quoteOrderQtyNew = this->safeString2(
              params, std::string("quoteOrderQty"), std::string("cost"));
          std::any precision =
              ::getValue(::getValue(market, std::string("precision")),
                         std::string("price"));
          if (isTrue(!isEqual(quoteOrderQtyNew, std::any{}))) {
            ::setValue(request, std::string("quoteOrderQty"),
                       this->decimalToPrecision(quoteOrderQtyNew, TRUNCATE,
                                                precision,
                                                this->precisionMode));
          } else if (isTrue(!isEqual(price, std::any{}))) {
            std::any amountString = this->numberToString(amount);
            std::any priceString = this->numberToString(price);
            std::any quoteOrderQuantity =
                ccxt::Precise::stringMul(amountString, priceString);
            ::setValue(request, std::string("quoteOrderQty"),
                       this->decimalToPrecision(quoteOrderQuantity, TRUNCATE,
                                                precision,
                                                this->precisionMode));
          } else {
            quantityIsRequired = true;
          }
        } else {
          quantityIsRequired = true;
        }
      } else {
        quantityIsRequired = true;
      }
    } else if (isTrue(isEqual(uppercaseType, std::string("LIMIT")))) {
      timeInForceIsRequired = true;
      quantityIsRequired = true;
      priceIsRequired = true;
    } else if (isTrue(isTrue((isEqual(uppercaseType, std::string("STOP")))) ||
                      isTrue((isEqual(uppercaseType,
                                      std::string("TAKE_PROFIT")))))) {
      quantityIsRequired = true;
      priceIsRequired = true;
      triggerPriceIsRequired = true;
    } else if (isTrue(isTrue((isEqual(uppercaseType,
                                      std::string("STOP_MARKET")))) ||
                      isTrue((isEqual(uppercaseType,
                                      std::string("TAKE_PROFIT_MARKET")))))) {
      if (isTrue(!isEqual(closePosition, true))) {
        quantityIsRequired = true;
      }
      triggerPriceIsRequired = true;
    } else if (isTrue(isEqual(uppercaseType,
                              std::string("TRAILING_STOP_MARKET")))) {
      ::setValue(request, std::string("callbackRate"), trailingPercent);
      if (isTrue(!isEqual(trailingTriggerPrice, std::any{}))) {
        ::setValue(request, std::string("activationPrice"),
                   this->priceToPrecision(symbol, trailingTriggerPrice));
      }
    }
    if (isTrue(quantityIsRequired)) {
      std::any marketAmountPrecision = this->safeString(
          ::getValue(market, std::string("precision")), std::string("amount"));
      std::any isPrecisionAvailable =
          (!isEqual(marketAmountPrecision, std::any{}));
      if (isTrue(isPrecisionAvailable)) {
        ::setValue(request, std::string("quantity"),
                   this->amountToPrecision(symbol, amount));
      } else {
        ::setValue(request, std::string("quantity"),
                   this->parseToNumeric(amount));
      }
    }
    if (isTrue(priceIsRequired)) {
      if (isTrue(isEqual(price, std::any{}))) {
        throw InvalidOrder(toString(
            add(add(add(this->id,
                        std::string(
                            " createOrder() requires a price argument for a ")),
                    type),
                std::string(" order"))));
      }
      std::any pricePrecision = this->safeString(
          ::getValue(market, std::string("precision")), std::string("price"));
      std::any isPricePrecisionAvailable =
          (!isEqual(pricePrecision, std::any{}));
      if (isTrue(isPricePrecisionAvailable)) {
        ::setValue(request, std::string("price"),
                   this->priceToPrecision(symbol, price));
      } else {
        ::setValue(request, std::string("price"), this->parseToNumeric(price));
      }
    }
    if (isTrue(triggerPriceIsRequired)) {
      if (isTrue(isEqual(stopPrice, std::any{}))) {
        throw InvalidOrder(toString(
            add(add(add(this->id, std::string(" createOrder() requires a "
                                              "stopPrice extra param for a ")),
                    type),
                std::string(" order"))));
      }
      if (isTrue(!isEqual(stopPrice, std::any{}))) {
        ::setValue(request, std::string("stopPrice"),
                   this->priceToPrecision(symbol, stopPrice));
      }
    }
    if (isTrue(isTrue(isTrue(timeInForceIsRequired) &&
                      isTrue((isEqual(
                          this->safeString(params, std::string("timeInForce")),
                          std::any{})))) &&
               isTrue((isEqual(
                   this->safeString(request, std::string("timeInForce")),
                   std::any{}))))) {
      std::any tif = std::any{};
      std::any tifparamsVariable = this->handleOptionAndParams(
          params, std::string("createOrder"), std::string("timeInForce"));
      tif = ::getValue(tifparamsVariable, 0);
      params = ::getValue(tifparamsVariable, 1);
      ::setValue(request, std::string("timeInForce"), tif);
    }
    std::any requestParams = this->omit(
        params,
        ccxt::list{
            std::string("newClientOrderId"), std::string("clientOrderId"),
            std::string("stopPrice"), std::string("triggerPrice"),
            std::string("trailingTriggerPrice"), std::string("trailingPercent"),
            std::string("trailingDelta"), std::string("stopPrice"),
            std::string("stopLossPrice"), std::string("takeProfitPrice")});
    if (isTrue(
            isTrue((isEqual(
                this->safeBool(this->options, std::string("builderFee")),
                true))) &&
            isTrue((isEqual(::getValue(market, std::string("swap")), true))))) {
      ::setValue(request, std::string("builder"),
                 this->safeString(this->options, std::string("builder")));
      ::setValue(request, std::string("feeRate"),
                 this->safeString(this->options, std::string("builderRate")));
    }
    return this->extend(request, requestParams);
  }

  /**
   * @method
   * @name aster#cancelAllOrders
   * @description cancel all open orders in a market
   * @see
   * https://asterdex.github.io/aster-api-website/spot-v3/account%26trades/#cancel-all-open-orders-trade
   * @see
   * https://asterdex.github.io/aster-api-website/futures-v3/account%26trades/#current-all-open-orders-user_data
   * @param {string} symbol unified market symbol of the market to cancel orders
   * in
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  cancelAllOrders(std::any symbol = std::any{},
                  std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(symbol, std::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id,
                       std::string(
                           " cancelAllOrders() requires a symbol argument"))));
                 }
                 awaitValue(this->loadMarketsAndSignIn());
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 std::any response = std::any{};
                 if (isTrue(isEqual(::getValue(market, std::string("swap")),
                                    true))) {
                   response = awaitValue(this->fapiPrivateDeleteV3AllOpenOrders(
                       this->extend(request, params)));
                 } else {
                   response = awaitValue(this->sapiPrivateDeleteV3AllOpenOrders(
                       this->extend(request, params)));
                 }
                 //
                 // SPOT & SWAP has same response
                 //
                 //     {
                 //         "code": "200",
                 //         "msg": "The operation of cancel all open order is
                 //         done."
                 //     }
                 //
                 return ccxt::list{this->safeOrder(ccxt::dict{
                     {std::string("info"), response},
                 })};
               })
        .share();
  }

  /**
   * @method
   * @name aster#cancelOrder
   * @description cancels an open order
   * @see
   * https://asterdex.github.io/aster-api-website/spot-v3/account%26trades/#cancel-order-trade
   * @see
   * https://asterdex.github.io/aster-api-website/futures-v3/account%26trades/#cancel-order-trade
   * @param {string} id order id
   * @param {string} symbol unified symbol of the market the order was made in
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} An [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  cancelOrder(std::any id, std::any symbol = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(symbol, std::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(
                               " cancelOrder() requires a symbol argument"))));
                 }
                 awaitValue(this->loadMarketsAndSignIn());
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 std::any clientOrderId =
                     this->safeString2(params, std::string("origClientOrderId"),
                                       std::string("clientOrderId"));
                 if (isTrue(!isEqual(clientOrderId, std::any{}))) {
                   ::setValue(request, std::string("origClientOrderId"),
                              clientOrderId);
                 } else {
                   ::setValue(request, std::string("orderId"), id);
                 }
                 params = this->omit(
                     params, ccxt::list{std::string("origClientOrderId"),
                                        std::string("clientOrderId")});
                 std::any response = std::any{};
                 if (isTrue(isEqual(::getValue(market, std::string("swap")),
                                    true))) {
                   response = awaitValue(this->fapiPrivateDeleteV3Order(
                       this->extend(request, params)));
                 } else {
                   response = awaitValue(this->sapiPrivateDeleteV3Order(
                       this->extend(request, params)));
                 }
                 return this->parseOrder(response, market);
               })
        .share();
  }

  /**
   * @method
   * @name aster#cancelOrders
   * @description cancel multiple orders
   * @see
   * https://asterdex.github.io/aster-api-website/spot-v3/account%26trades/#cancel-all-open-orders-trade
   * @see
   * https://asterdex.github.io/aster-api-website/futures-v3/account%26trades/#cancel-multiple-orders-trade
   * @param {string[]} ids order ids
   * @param {string} [symbol] unified market symbol
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   *
   * EXCHANGE SPECIFIC PARAMETERS
   * @param {string[]} [params.origClientOrderIdList] max length 10 e.g.
   * ["my_id_1","my_id_2"], encode the double quotes. No space after comma
   * @param {int[]} [params.recvWindow]
   * @returns {object} an list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  cancelOrders(std::any ids, std::any symbol = std::any{},
               std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(symbol, std::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(
                               " cancelOrders() requires a symbol argument"))));
                 }
                 awaitValue(this->loadMarketsAndSignIn());
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 std::any clientOrderIdList = this->safeList(
                     params, std::string("origClientOrderIdList"));
                 if (isTrue(!isEqual(clientOrderIdList, std::any{}))) {
                   ::setValue(request, std::string("origClientOrderIdList"),
                              clientOrderIdList);
                 } else {
                   ::setValue(request, std::string("orderIdList"), ids);
                 }
                 std::any response = std::any{};
                 if (isTrue(isEqual(::getValue(market, std::string("swap")),
                                    true))) {
                   response = awaitValue(this->fapiPrivateDeleteV3BatchOrders(
                       this->extend(request, params)));
                 } else {
                   response = awaitValue(this->sapiPrivateDeleteV3AllOpenOrders(
                       this->extend(request, params)));
                 }
                 return this->parseOrders(response, market);
               })
        .share();
  }

  /**
   * @method
   * @name aster#setLeverage
   * @description set the level of leverage for a market
   * @see
   * https://asterdex.github.io/aster-api-website/futures-v3/account%26trades/#change-initial-leverage-trade
   * @param {float} leverage the rate of leverage
   * @param {string} symbol unified market symbol
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} response from the exchange
   */
  std::shared_future<std::any>
  setLeverage(std::any leverage, std::any symbol = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(symbol, std::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(
                               " setLeverage() requires a symbol argument"))));
                 }
                 if (isTrue(isTrue((isLessThan(leverage, 1))) ||
                            isTrue((isGreaterThan(leverage, 125))))) {
                   throw BadRequest(toString(add(
                       this->id,
                       std::string(" leverage should be between 1 and 125"))));
                 }
                 awaitValue(this->loadMarketsAndSignIn());
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                     {std::string("leverage"), leverage},
                 };
                 std::any response = awaitValue(this->fapiPrivatePostV3Leverage(
                     this->extend(request, params)));
                 //
                 //     {
                 //         "leverage": 21,
                 //         "maxNotionalValue": "1000000",
                 //         "symbol": "BTCUSDT"
                 //     }
                 //
                 return response;
               })
        .share();
  }

  /**
   * @method
   * @name aster#fetchLeverages
   * @description fetch the set leverage for all markets
   * @see
   * https://asterdex.github.io/aster-api-website/futures-v3/account%26trades/#position-information-v3-user_data
   * @param {string[]} [symbols] a list of unified market symbols
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a list of [leverage structures]{@link
   * https://docs.ccxt.com/?id=leverage-structure}
   */
  std::shared_future<std::any>
  fetchLeverages(std::any symbols = std::any{},
                 std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 awaitValue(this->loadMarketsAndSignIn());
                 std::any response =
                     awaitValue(this->fapiPrivateGetV3PositionRisk(params));
                 //
                 //     [
                 //         {
                 //             "symbol": "INJUSDT",
                 //             "positionAmt": "0.0",
                 //             "entryPrice": "0.0",
                 //             "markPrice": "0.00000000",
                 //             "unRealizedProfit": "0.00000000",
                 //             "liquidationPrice": "0",
                 //             "leverage": "20",
                 //             "maxNotionalValue": "25000",
                 //             "marginType": "cross",
                 //             "isolatedMargin": "0.00000000",
                 //             "isAutoAddMargin": "false",
                 //             "positionSide": "BOTH",
                 //             "notional": "0",
                 //             "isolatedWallet": "0",
                 //             "updateTime": 0
                 //         }
                 //     ]
                 //
                 return this->parseLeverages(this->toArray(response), symbols,
                                             std::string("symbol"));
               })
        .share();
  }

  std::any parseLeverage(std::any leverage,
                         std::any market = std::any{}) override {
    //
    //     {
    //         "symbol": "INJUSDT",
    //         "positionAmt": "0.0",
    //         "entryPrice": "0.0",
    //         "markPrice": "0.00000000",
    //         "unRealizedProfit": "0.00000000",
    //         "liquidationPrice": "0",
    //         "leverage": "20",
    //         "maxNotionalValue": "25000",
    //         "marginType": "cross",
    //         "isolatedMargin": "0.00000000",
    //         "isAutoAddMargin": "false",
    //         "positionSide": "BOTH",
    //         "notional": "0",
    //         "isolatedWallet": "0",
    //         "updateTime": 0
    //     }
    //
    std::any marketId = this->safeString(leverage, std::string("symbol"));
    std::any marginMode =
        this->safeStringLower(leverage, std::string("marginType"));
    std::any side =
        this->safeStringLower(leverage, std::string("positionSide"));
    std::any longLeverage = std::any{};
    std::any shortLeverage = std::any{};
    std::any leverageValue =
        this->safeInteger(leverage, std::string("leverage"));
    if (isTrue(isTrue((isEqual(side, std::any{}))) ||
               isTrue((isEqual(side, std::string("both")))))) {
      longLeverage = leverageValue;
      shortLeverage = leverageValue;
    } else if (isTrue(isEqual(side, std::string("long")))) {
      longLeverage = leverageValue;
    } else if (isTrue(isEqual(side, std::string("short")))) {
      shortLeverage = leverageValue;
    }
    return ccxt::dict{
        {std::string("info"), leverage},
        {std::string("symbol"), this->safeSymbol(marketId, market)},
        {std::string("marginMode"), marginMode},
        {std::string("longLeverage"), longLeverage},
        {std::string("shortLeverage"), shortLeverage},
    };
  }

